%[text] ======================= Helper Functions =======================
function [S, F, v_I] = solve_direct_balance(A_S, A_F, d_S, d_F, w, V_I, K_S, K_F)
    % Solve d_S*S + w*r(S,F) = A_S and d_F*F + w*r(S,F) = A_F.
    % For a time step: A = old + dt*production, d = 1+dt*gamma, w=dt.
    % For equilibrium: A = production, d = gamma, w=1.
    % r(S,F) = V_I*S/(K_S+S)*F/(K_F+F), with 1:1 consumption.
    %
    % We solve for the remaining fraction of the smaller available pool.
    % This avoids subtracting almost equal numbers when cancellation removes
    % nearly all of one species. No subtraction is imposed as a readout;
    % the root is determined by the finite chemical reaction rate.
    args = [A_S, A_F, d_S, d_F, w, V_I, K_S, K_F];
    if ~isreal(args) || any(~isfinite(args)) || ...
            any([A_S, A_F, w, V_I] < 0) || any([d_S, d_F, K_S, K_F] <= 0)
        error('DirectCancellation:InvalidInput', ...
            'Use finite nonnegative pools/rates and strictly positive denominators/Km.');
    end

    if A_S == 0 || A_F == 0 || V_I == 0 || w == 0
        S = A_S/d_S;
        F = A_F/d_F;
        v_I = V_I*(S/(K_S+S))*(F/(K_F+F));
        return
    end

    if A_S <= A_F
        smaller = A_S;
        S_of_z = @(z) (smaller*z)/d_S;
        F_of_z = @(z) ((A_F-A_S) + smaller*z)/d_F;
    else
        smaller = A_F;
        S_of_z = @(z) ((A_S-A_F) + smaller*z)/d_S;
        F_of_z = @(z) (smaller*z)/d_F;
    end

    % At z=0 one substrate is zero; at z=1 no shared consumption occurred.
    % The root enforces: smaller*(1-z) = w*r(Snew,Fnew).
    % Avoid division by smaller, which can be extremely close to zero.
    balance = @(z) smaller*(z-1) + w*V_I * ...
        (S_of_z(z)/(K_S+S_of_z(z))) * ...
        (F_of_z(z)/(K_F+F_of_z(z)));

    persistent root_options
    if isempty(root_options)
        % Small residual fractions require relative, not a coarse absolute,
        % accuracy in z. fzero retains its machine-precision safeguards.
        root_options = optimset('Display','off','TolX',realmin);
    end
    [z, ~, exitflag] = fzero(balance, [0 1], root_options);
    if exitflag <= 0 || ~isfinite(z) || z < 0 || z > 1
        error('DirectCancellation:RootFailure', ...
            'The coupled cancellation balance did not converge within [0,1].');
    end
    S = S_of_z(z);
    F = F_of_z(z);
    v_I = V_I*(S/(K_S+S))*(F/(K_F+F));
end

function addingPathParentFolderByName(targetName)
    % Start from the current directory
    currFolder = pwd;
    found = false;
    
    % Continue searching until you reach the root folder
    while true
        % Get the parent folder
        [parentFolder, currentName] = fileparts(currFolder);
        
        % Check if the current folder's name is the target
        if strcmpi(currentName, targetName)
            found = true;
            break;
        end
        
        % If we've reached the root or no change, exit the loop
        if isempty(parentFolder) || strcmp(currFolder, parentFolder)
            break;
        end
        
        % Move one level up
        currFolder = parentFolder;
    end

    if found
        addpath(genpath(currFolder));
        fprintf('Adding matlab path to: %s\n', currFolder);
    else
        error('Folder named "%s" not found in any parent directory.', targetName);
    end
end

